data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_0f4a7af55e9b7258016ae355fa266c87d1ae5389b8967426b0","logprobs":[],"output_index":0,"sequence_number":744,"text":"<main>\n  <small>ALDER &amp; BEAN · COFFEE SHOP</small>\n  <h1>Good morning</h1>\n  <p>Order a little something lovely.</p>\n\n  <h2>Popular today</h2>\n  <section style=\"display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem\">\n    <article>\n      <h3>Oat Latte</h3>\n      <p>Espresso, silky oat milk</p>\n      <p><strong>$5.25</strong></p>\n      <button type=\"button\" data-add=\"Oat Latte\" data-price=\"5.25\">Add</button>\n    </article>\n    <article>\n      <h3>Honey Cappuccino</h3>\n      <p>Local honey, cinnamon</p>\n      <p><strong>$4.75</strong></p>\n      <button type=\"button\" data-add=\"Honey Cappuccino\" data-price=\"4.75\">Add</button>\n    </article>\n    <article>\n      <h3>Cold Brew</h3>\n      <p>Slow-steeped, smooth finish</p>\n      <p><strong>$4.50</strong></p>\n      <button type=\"button\" data-add=\"Cold Brew\" data-price=\"4.50\">Add</button>\n    </article>\n    <article>\n      <h3>Butter Croissant</h3>\n      <p>Freshly baked each morning</p>\n      <p><strong>$3.25</strong></p>\n      <button type=\"button\" data-add=\"Butter Croissant\" data-price=\"3.25\">Add</button>\n    </article>\n  </section>\n\n  <article>\n    <h2>Your order <small id=\"count\">0 items</small></h2>\n    <ul id=\"order\"><li>Your picks will appear here.</li></ul>\n    <p><strong>Total <span id=\"total\">$0.00</span></strong></p>\n    <button id=\"checkout\" type=\"button\" data-action=\"Checkout screen for a coffee shop order\">Checkout</button>\n  </article>\n</main>\n<script>\nconst order = new Map();\nconst money = n => '$' + n.toFixed(2);\nfunction render() {\n  const list = document.getElementById('order');\n  list.replaceChildren();\n  let qty = 0, total = 0;\n  for (const [name, item] of order) {\n    qty += item.qty;\n    total += item.qty * item.pri